//! 🧪️ A staged original member survives physical closure of its preparation decoder before an independent decision.
use super::*;
use store::SpaceMember;
use store::os_store::one_item::{ArtifactStoreOneItemGrant,ArtifactStoreOneItemPreparationStep};
fn close_original_decoder(caller:&mut OriginalJobFixtureCaller,decoder:&mut OriginalJobDecodeOwner,g:RetainedCloneGrant){for _ in 0..262144{if decoder.terminal_is_empty(){break}caller.turn(g,|cx|cx.with_original_retirement(|cx|{let d=decoder.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|decoder.close_step(grant))?;Ok(())})).unwrap();}assert!(decoder.terminal_is_empty());}
#[test]
fn original_staged_member_hands_independent_owned_candidate_to_commit_or_abort(){
 let law:serde_json::Value=serde_json::from_str(include_str!("🔣️.json")).unwrap();
 for decision in law["decisions"].as_array().unwrap(){
  let mut prepare_caller=caller();let mut prepare_decoder=OriginalJobDecodeOwner::empty();let mut store=native_document_store(&mut prepare_caller,&mut prepare_decoder);
  let g=RetainedCloneGrant{maximum_copy_bytes:32768,maximum_capacity_bytes:16<<20,maximum_release_bytes:16<<20,..TURN};
  let mut values=Some(vec![Mutation::Zoom{zoom:law["operation"]["zoom"].as_f64().unwrap()}]);
  let batch=turn(&mut prepare_caller,&mut prepare_decoder,g,|cx|{let(batch,p)=store::os_store::MemberStoreOwnedBatch::admit(&mut values,cx.retained_grant())?.unwrap();cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64);Ok(batch)});
  let mut request=store::os_store::MemberStoreOwnedBatchRequest{operation:OperationId(8701),expected_generation:store.generation(),expected_revision:store.content_revision(),actor:semio_framework_value::SharedUtf8::from("original-transaction"),group_id:Some(String::from("original-transaction")),transaction:None,mutations:batch};
  let mut publication=turn(&mut prepare_caller,&mut prepare_decoder,g,|cx|{let(owner,p)=store.begin_one_item_owned_publication(&mut request,ArtifactStoreOneItemGrant::from_retained(cx.retained_grant())).unwrap().unwrap();cx.consume_retained(p)?;cx.consume_fuel(1);Ok(owner)});
  let mut origins=Some(std::collections::VecDeque::from([protocol::MutationOrigin::Contributed{plugin_id:law["origin"]["pluginId"].as_str().unwrap().into(),mutation_id:protocol::SchemaId(law["origin"]["mutationId"].as_str().unwrap().into()),payload_hash:protocol::PayloadHash([7;32])}]));let origin_pointer=match origins.as_ref().unwrap().front().unwrap(){protocol::MutationOrigin::Contributed{plugin_id,..}=>plugin_id.as_ptr(),_=>unreachable!()};
  turn(&mut prepare_caller,&mut prepare_decoder,g,|cx|{let step=publication.admit_original_origins(&mut origins,cx.retained_grant())?;assert!(matches!(step,RetainedCloneStep::Complete(_)));cx.consume_retained(step.progress())?;cx.consume_fuel(step.progress().copied_items as u64);Ok(())});assert!(origins.is_none());
  let mut ready=false;
  for index in 0..262144{let step=turn(&mut prepare_caller,&mut prepare_decoder,g,|cx|{let grant=cx.retained_grant();let step=cx.with_native_receiving(|control|store.prepare_one_item_publication(publication.as_mut(),4096,ArtifactStoreOneItemGrant::from_retained(grant),control).map_err(|message|ValueError::new(ValueRefusalKind::InvalidValue,message))).unwrap();let p=step.ownership_progress();if let Some(issued)=cx.receiving_issued_grant(){cx.consume_receiving_retained(issued,p)?;}else{cx.consume_retained(p)?;}cx.consume_fuel(p.copied_items as u64);Ok(step)});if matches!(step,ArtifactStoreOneItemPreparationStep::Prepared(..)){ready=true;break}assert!(index<262143,"original member preparation stalled");}
  assert!(ready);assert_eq!(store.snapshot_ref().zoom,law["input"]["zoom"].as_f64().unwrap());
  let metadata=publication.prepared_operation_metadata(0).unwrap();let protocol::MutationOrigin::Contributed{plugin_id,mutation_id,payload_hash}=&metadata.origin else{panic!("prepared native provenance was replaced")};assert_eq!(plugin_id.as_ptr(),origin_pointer);assert_eq!(plugin_id,law["origin"]["pluginId"].as_str().unwrap());assert_eq!(mutation_id.0,law["origin"]["mutationId"].as_str().unwrap());assert_eq!(payload_hash.0,[7;32]);
  close_original_decoder(&mut prepare_caller,&mut prepare_decoder,g);prepare_caller.retire(g);drop(prepare_decoder);
  let mut decision_caller=caller();let mut decision_decoder=OriginalJobDecodeOwner::empty();
  if decision=="commit"{
   let(mut visibility,shared)=turn(&mut decision_caller,&mut decision_decoder,g,|cx|{let capacity=store::os_vcs::ArtifactGroupVisibilityOwner::allocation_bytes();let copy=2*size_of::<store::os_vcs::ArtifactGroupVisibilityOwner>();assert!(capacity<=cx.retained_grant().maximum_capacity_bytes&&copy<=cx.retained_grant().maximum_copy_bytes);let visibility=store::os_vcs::ArtifactGroupVisibilityOwner::new();let shared=visibility.view();cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:copy,retained_capacity_bytes:capacity,..Default::default()})?;cx.consume_fuel(1);Ok((visibility,shared))});let mut staged=false;
   for index in 0..262144{let step=turn(&mut decision_caller,&mut decision_decoder,g,|cx|{let step=store.stage_one_item_publication(publication.as_mut(),&shared,ArtifactStoreOneItemGrant::from_retained(cx.retained_grant())).unwrap();let p=step.ownership_progress();cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64);Ok(step)});if matches!(step,ArtifactStoreOneItemPreparationStep::Prepared(..)){staged=true;break}assert!(index<262143);}
   assert!(staged);assert!(visibility.commit());
   let mut adopted=false;for index in 0..262144{let step=turn(&mut decision_caller,&mut decision_decoder,g,|cx|{let step=store.adopt_one_item_publication(publication.as_mut(),&shared,ArtifactStoreOneItemGrant::from_retained(cx.retained_grant())).unwrap();let p=step.ownership_progress();cx.consume_retained(p)?;cx.consume_fuel(p.copied_items as u64);Ok(step)});if matches!(step,ArtifactStoreOneItemPreparationStep::Prepared(..)){adopted=true;break}assert!(index<262143);}assert!(adopted);
   let shared=turn(&mut decision_caller,&mut decision_decoder,g,|cx|{let copy=size_of::<semio_framework_value::FactoryAuthority>();cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:copy,..Default::default()})?;cx.consume_fuel(1);Ok(semio_framework_value::FactoryAuthority::new(shared))});close_typed(shared,&mut decision_caller,&mut decision_decoder);
   let visibility=turn(&mut decision_caller,&mut decision_decoder,g,|cx|{let copy=size_of::<semio_framework_value::FactoryAuthority>();cx.consume_retained(RetainedCloneProgress{copied_items:1,copied_bytes:copy,..Default::default()})?;cx.consume_fuel(1);Ok(visibility.into_retirement())});close_typed(visibility,&mut decision_caller,&mut decision_decoder);
  }
  assert_eq!(store.snapshot_ref().zoom,law["expected"][decision.as_str().unwrap()].as_f64().unwrap());
  for index in 0..262144{if publication.terminal_is_empty(){break}turn(&mut decision_caller,&mut decision_decoder,g,|cx|cx.with_original_retirement(|cx|{let d=publication.retirement_demands(4096)?;close_original_retained_step(cx,d,|grant|store.abort_one_item_publication(publication.as_mut(),grant).map_err(|error|error))?;Ok(())}));assert!(index<262143,"independent original member close stalled");}
  assert!(publication.terminal_is_empty());let release=size_of_val(publication.as_ref());turn(&mut decision_caller,&mut decision_decoder,g,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,RetirementDemand{release_bytes:release,depth:1,..Default::default()},|_|{drop(publication);Ok(RetainedCloneStep::Progress(RetainedCloneProgress{copied_items:1,released_bytes:release,..Default::default()}))})?;Ok(())}));
  for _ in 0..262144{if request.mutations.terminal_is_empty(){break}let d=request.mutations.next_demands(4096).unwrap();turn(&mut decision_caller,&mut decision_decoder,g,|cx|cx.with_original_retirement(|cx|{close_original_retained_step(cx,d,|grant|request.mutations.close_granted(grant))?;Ok(())}));}assert!(request.mutations.terminal_is_empty());drop(request);
  for index in 0..1048576{if store.close_owned_store_terminal_is_empty(){break}turn(&mut decision_caller,&mut decision_decoder,g,|cx|cx.with_original_retirement(|cx|{let d=store.close_owned_demands(4096)?;close_original_retained_step(cx,d,|grant|store.close_owned_store_step(grant))?;Ok(())}));assert!(index<1048575);}release_native_store_box(store,&mut decision_caller,&mut decision_decoder);close_original_decoder(&mut decision_caller,&mut decision_decoder,g);decision_caller.retire(g);
 }
}
